statement.tex:
次の関数を微分せよ（(4) は第2次導関数を求めよ）．
\begin{enumerate}
  \item $y=x^2e^{-x}$ \qquad (2) $y=\log\bigl(x+\sqrt{x^2+1}\bigr)$
  \setcounter{enumi}{2}
  \item $y=\dfrac{\sin x}{1+\cos x}$ \qquad (4) $y=e^x\cos x$
\end{enumerate}

\begin{enumerate}
  \item $y=x^{\frac1x}\ (x>0)$ を微分し，$y$ が最大となる $x$ を求めよ．
  \item アステロイド $x=\cos^3t,\ y=\sin^3t\ \bigl(0<t<\frac\pi2\bigr)$ 上の点における接線が $x$ 軸，$y$ 軸と交わる点を A，B とするとき，AB の長さは一定であることを示せ．
  \item 曲線 $x^2+xy+y^2=7$ 上の点 $(1,2)$ における接線の方程式を求めよ．
\end{enumerate}

$f(x)=x^2\sin\dfrac1x\ (x\neq0)$，$f(0)=0$ とする．
\begin{enumerate}
  \item $f(x)$ は $x=0$ で微分可能であることを示し，$f'(0)$ を求めよ．
  \item $x\neq0$ での $f'(x)$ を求め，$\displaystyle\lim_{x\to0}f'(x)$ は存在しないことを示せ．
\end{enumerate}

$f(x)=\dfrac{x^2-x+1}{x-1}$ とする．
\begin{enumerate}
  \item $f(x)$ の極値と，$y=f(x)$ の漸近線を求めよ．
  \item 方程式 $f(x)=k$ の実数解の個数を $k$ の値によって分類せよ．
\end{enumerate}

$a$ を定数とし，$f(x)=\dfrac{x+a}{x^2+1}$ とする．
\begin{enumerate}
  \item $f(x)$ の最大値と最小値を $a$ で表せ．
  \item 最大値が1となる $a$ を求め，そのときの最小値を求めよ．
\end{enumerate}

曲線 $y=\log x$ 上の点 A$(1,0)$ と，点 Q$(t,\log t)\ (t\neq1)$ における法線の交点を R とする．
\begin{enumerate}
  \item A における法線の方程式を求めよ．
  \item $t\to1$ のとき R が近づく点を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $3^\pi$ と $\pi^3$ の大小を比較せよ．
  \item $x<y$ を満たす自然数の組で $x^y=y^x$ となるものをすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\log x$ が上に凸であることを使って，正の数 $a,b$ について $a^{\frac13}b^{\frac23}\leqq\dfrac{a}{3}+\dfrac{2b}{3}$ を示せ．
  \item $\triangle ABC$ において $\sin A+\sin B+\sin C\leqq\dfrac{3\sqrt3}2$ を示せ（$\sin x$ が $0<x<\pi$ で上に凸であることを用いてよい）．
\end{enumerate}

\begin{enumerate}
  \item $0<a<b$ のとき，$\dfrac{b-a}{b}<\log b-\log a<\dfrac{b-a}{a}$ を示せ．
  \item 自然数 $n$ に対して $\Bigl(1+\dfrac1n\Bigr)^n<e<\Bigl(1+\dfrac1n\Bigr)^{n+1}$ を示せ．
\end{enumerate}

$x>0$ に対し $f(x)=\dfrac{\log x}{x^2}$ とする．
\begin{enumerate}
  \item $n=1,2,\dots$ に対し $f^{(n)}(x)=\dfrac{a_n+b_n\log x}{x^{n+2}}$ と表されることを示し，$a_n,b_n$ の漸化式を求めよ．
  \item $h_n=\displaystyle\sum_{k=1}^n\frac1k$ とおく．$a_n,b_n$ の一般項を $h_n$ を用いて表せ．
\end{enumerate}

\begin{enumerate}
  \item $0<\theta<\dfrac\pi2$ のとき，$2\sin\theta+\tan\theta>3\theta$ を証明せよ．
  \item (1) を用いて $\pi<2+\dfrac{2\sqrt3}{3}$ を示せ．
\end{enumerate}

$a$ を定数とし，$f(x)=\dfrac{a-\sin x}{a+\cos x}$ とする．
\begin{enumerate}
  \item $f(x)$ が $0<x<\dfrac\pi2$ の範囲で極大値をもつような $a$ の値の範囲を求めよ．
  \item $f'(x)=0$ となる点 $x$ では $f(x)=\dfrac{\cos x}{\sin x}$ となることを示せ．
  \item 極大値が $2+\sqrt3$ となるときの $a$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x>0$ のとき $\dfrac1{x+1}<\log(x+1)-\log x<\dfrac1x$ を示せ．
  \item $x>0$ のとき $\Bigl(1+\dfrac1x\Bigr)^x<e<\Bigl(1+\dfrac1x\Bigr)^{x+1}$ を示せ．
  \item 自然数 $n$ に対し $0<e-\Bigl(1+\dfrac1n\Bigr)^n<\dfrac{e}{n+1}$ を示せ．
\end{enumerate}

半径 $a$ の球に外接する直円すいについて，
\begin{enumerate}
  \item 底面の半径を $x$ とするとき，高さ $h$ を $x$ で表せ．
  \item 直円すいの体積 $V$ と表面積（底面を含む）$S$ の間に $V=\dfrac13aS$ が成り立つことを示せ．
  \item $S$ の最小値と，そのときの $x$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 曲線 $y=\dfrac{e^x}{x^2}$ の概形をかけ．
  \item 定数 $k$ に対して，方程式 $e^x=kx^2$ の異なる実数解の個数を求めよ．
\end{enumerate}

関数 $f(x)=\dfrac{x^2+ax+b}{x^2+1}$ は $x=1$ で極大値 $3$ をとる．
\begin{enumerate}
  \item $a,b$ の値を求めよ．
  \item $f(x)$ の極小値を求めよ．
  \item 曲線 $y=f(x)$，直線 $y=1$，直線 $x=1$ で囲まれた部分の面積を求めよ．
\end{enumerate}

曲線 $y=\log x$ 上の点 $(t,\log t)\ (1\leqq t\leqq e)$ における接線を $l$ とする．
\begin{enumerate}
  \item $l$ は $1\leqq x\leqq e$ で $x$ 軸より上にあることを示せ．
  \item $l$，$x$ 軸，2直線 $x=1$，$x=e$ で囲まれた台形の面積 $S(t)$ を求めよ．
  \item $S(t)$ の最小値と最大値を求めよ．
\end{enumerate}

$a>1$ を定数とする．
\begin{enumerate}
  \item 不等式 $a^x\geqq x^2$ がすべての正の数 $x$ に対して成り立つような $a$ の範囲を求めよ．
  \item 不等式 $a^x\geqq x^a$ がすべての正の数 $x$ に対して成り立つような $a$ を求めよ．
\end{enumerate}

$k$ を正の整数とし，$(2k-1)\pi\leqq x\leqq2k\pi$ で定義された2曲線 $C_1:y=\cos x$，$C_2:y=\dfrac{1-x^2}{1+x^2}$ を考える．
\begin{enumerate}
  \item $x$ が $C_1$ と $C_2$ の共有点の $x$ 座標であることは，$\tan\dfrac x2=-x$ と同値であることを示せ．
  \item 共有点はただ1つであることを示せ．その $x$ 座標を $x_k$ とする．
  \item $\displaystyle\lim_{k\to\infty}k\{x_k-(2k-1)\pi\}$ を求めよ．
\end{enumerate}

$n$ を自然数とし，$\cos n\theta=f_n(\cos\theta)$ をみたす $n$ 次の整数係数多項式 $f_n(x)$ を考える（$f_0=1$）．
\begin{enumerate}
  \item $f_{n+1}(x)=2xf_n(x)-f_{n-1}(x)$ を示し，$f_n$ の最高次の係数を求めよ．
  \item 自然数 $m,n$ に対し $f_m(f_n(x))=f_{mn}(x)$ を示せ．
  \item $f_n(x)$ の係数の絶対値の和は $\dfrac{(1+\sqrt2)^n+(1-\sqrt2)^n}2$ であることを示せ．
\end{enumerate}

2以上の自然数 $n$ に対し $f_n(x)=2-x-2e^{-nx}$ とする．
\begin{enumerate}
  \item $f_n(x)$ の最大値とそのときの $x$ を求めよ．
  \item $f_n(x)=0$ の正の解はただ1つであることを示し，それを $a_n$ とするとき $\displaystyle\lim_{n\to\infty}a_n=2$ を示せ．
  \item $\displaystyle\lim_{n\to\infty}\int_0^{a_n}f_n(x)\,dx$ を求めよ．
\end{enumerate}

2曲線 $C_1:y=e^x$，$C_2:y=\log x$ について，
\begin{enumerate}
  \item 原点から $C_1$，$C_2$ に引いた接線をそれぞれ求めよ．
  \item $C_1$，$C_2$ の両方に接する直線はちょうど2本あることを示し，それらの傾きの積を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x>0$ のとき $\log\Bigl(1+\dfrac1x\Bigr)>\dfrac1{x+1}$ を示し，$f(x)=x\log\Bigl(1+\dfrac1x\Bigr)$ が増加関数であることを示せ．
  \item $\Bigl(1+\dfrac{99}{100}\Bigr)^{\frac{100}{99}}$ と $\Bigl(1+\dfrac{100}{99}\Bigr)^{\frac{99}{100}}$ の大小を比較せよ．
\end{enumerate}

\begin{enumerate}
  \item 関数 $f(x)=x^{\log x}$（$x>0$）の導関数を求めよ．
  \item $y=(\sin x)^{\cos x}$（$0<x<\frac\pi2$）の導関数を求めよ．
  \item 曲線 $x^{\frac23}+y^{\frac23}=1$（$x>0,\ y>0$）について，導関数 $y'$ と2階導関数 $y''$ を $x,y$ で表せ．
\end{enumerate}

$xy$ 平面上の曲線 $C$ を $x=\cos^3t$，$y=\sin^3t$（$0<t<\frac\pi2$）で定義する．
\begin{enumerate}
  \item $\dfrac{dy}{dx}$，$\dfrac{d^2y}{dx^2}$ を $t$ で表せ．
  \item 曲線 $C$ 上の点 P における接線と $x$ 軸，$y$ 軸との交点をそれぞれ Q，R とするとき，線分 QR の長さは一定であることを示せ．
\end{enumerate}

関数 $f(x)=\dfrac{x^2+ax+b}{x-c}$ が $x=c+\alpha$（$\alpha>0$）で極値をとるとき，以下の問に答えよ．
\begin{enumerate}
  \item $f(x)$ は $x=c-\alpha$ でも極値をとることを示せ．
  \item $f(x)$ の極大値から極小値を引いた値を $\alpha$ で表せ．
  \item 2つの極値をとる点を結ぶ線分の中点は，曲線 $y=f(x)$ の斜めの漸近線上にあることを示せ．
\end{enumerate}

曲線 $C:\ y=\log x$ 上の異なる2点 A$(a,\log a)$，P$(t,\log t)$ における $C$ のそれぞれの法線の交点を Q として，線分 AQ の長さを $L_a(t)$ で表す．さらに $r(a)=\displaystyle\lim_{t\to a}L_a(t)$ と定義する．
\begin{enumerate}
  \item $r(a)$ を求めよ．
  \item $a$ が正の実数全体を動くとき，$r(a)$ の最小値を求めよ．
\end{enumerate}

$a$ は定数とする．関数 $f(x)=\sin x\cos x-a\cos x+(2a-1)x$（$-\frac\pi2<x<\frac\pi2$）について，
\begin{enumerate}
  \item $f'(x)$ を $\sin x$ の式で表せ．
  \item $f(x)$ が極大値と極小値をもつように，定数 $a$ の値の範囲を定めよ．
  \item $y=f(x)$ のグラフが変曲点をもち，その変曲点における接線の傾きが1であるように，定数 $a$ の値を定めよ．
\end{enumerate}

\begin{enumerate}
  \item $x>0$ のとき，$\dfrac{x^3}{e^x}<\dfrac{24}x$ を示せ．
  \item (1) を用いて，$\displaystyle\lim_{x\to\infty}x^3e^{-x}=0$ を示せ．
  \item $k$ を実数とするとき，$x$ の方程式 $x^2-x-1=ke^x$ の実数解の個数を求めよ．
\end{enumerate}

関数 $f(x)=x^2e^{-x}$ について，次の問に答えよ．
\begin{enumerate}
  \item 関数 $f(x)$ の増減，極値を調べて，曲線 $y=f(x)$ の概形を述べよ．
  \item $x$ 軸上の点 $(a,0)$ から，曲線 $y=f(x)$ への接線を3本ひくことができるような $a$ の値の範囲を求めよ．
\end{enumerate}

$x>0$ の範囲で，関数 $f(x)=\dfrac{\sin x}x$ を考える．
\begin{enumerate}
  \item $f(x)$ は $0<x\leqq\pi$ において減少することを示せ．
  \item $n$ を自然数とする．$f(x)$ が極値をとる $x$ は，区間 $n\pi<x<n\pi+\frac\pi2$ にちょうど1つずつ存在することを示せ．
  \item (2) の $x$ を $x_n$ とするとき，$\displaystyle\lim_{n\to\infty}(x_n-n\pi)$ を求めよ．
\end{enumerate}

関数 $f(x)$ は任意の実数 $x$ に対して定義されているとする．
\begin{enumerate}
  \item $f(x)$ が $x=a$ において微分可能であることの定義を述べよ．
  \item $f(x)=x\sin\dfrac1x$（$x\neq0$），$f(0)=0$ とする．$f(x)$ は $x=0$ で連続であるが微分可能でないことを示せ．
  \item 関数 $f(x)=\sin x$ が $x=a$ において微分可能であることを，(1) の定義を用いて証明せよ．
\end{enumerate}

$x>0$ に対し $f(x)=\dfrac{\log x}{x^2}$ とする．
\begin{enumerate}
  \item $n=0,1,2,\dots$ に対し $f(x)$ の第 $n$ 次導関数は，数列 $\{a_n\}$，$\{b_n\}$ を用いて $f^{(n)}(x)=\dfrac{a_n+b_n\log x}{x^{n+2}}$ と表されることを示し，$a_n,b_n$ に関する漸化式を求めよ（$a_0=0,\ b_0=1$）．
  \item $h_n=\displaystyle\sum_{k=1}^n\frac1k$ とおく．$h_n$ を用いて $a_n,b_n$ の一般項を求めよ．
\end{enumerate}

関数 $f(x)$ はすべての実数 $x$ に対して定義された関数で，任意の実数 $x,y$ に対して $f(x+y)=f(x)+f(y)+2xy$ を満たし，$f'(0)=a$ である．
\begin{enumerate}
  \item $f(0)$ を求めよ．
  \item $f(x)$ は微分可能な関数であることを示し，$f'(x)$ を求めよ．
  \item $f(x)$ を求めよ．
\end{enumerate}

定数でない多項式 $f(x)$ が等式 $f(x)=\{f'(x)\}^2$ を満たすとき，
\begin{enumerate}
  \item $f(x)$ の次数を求めよ．
  \item $f(x)$ を求め，方程式 $f(x)=0$ は重解をもつことを示せ．
\end{enumerate}

放物線 $y=x^2$ 上に3点A，B，Cがあり，$\triangle$ABC は $\angle$B を直角とする直角二等辺三角形である．A，B，C の $x$ 座標をそれぞれ $a,b,c$ とするとき $a<b<c$ をみたし，直線BCの傾き $m$ は正であるとする．
\begin{enumerate}
  \item $a,b,c$ をそれぞれ $m$ の分数式で表せ．
  \item $\triangle$ABC の面積 $T$ を $m$ で表し，$T$ の最小値とそのときの $m$ を求めよ．
\end{enumerate}

関数 $g(x)=xe^x+(2-e^x)\log(2-e^x)$（$x<\log2$）について，次の問に答えよ．
\begin{enumerate}
  \item $g(x)$ の増減と極値を調べ，$y=g(x)$ のグラフの概形を描け．ただし，グラフの凹凸は調べなくてよい．必要なら，$\displaystyle\lim_{x\to-\infty}xe^x=0$，$\displaystyle\lim_{u\to+0}u\log u=0$ を用いてもよい．
  \item 曲線 $C_1:y=e^x+k$ と曲線 $C_2:y=2x-e^x$ が共通接線をもつような，実数 $k$ の範囲を求めよ．また，共通接線がちょうど1本となる $k$ を求めよ．
\end{enumerate}

曲線 $C:y=(2-\cos x)\sin x$（$0\leqq x\leqq2\pi$）がある．次の問いに答えなさい．
\begin{enumerate}
  \item 曲線 $C$ の概形をかきなさい．ただし，凹凸は調べなくてよい．
  \item 曲線 $C$ 上に2点をとり，その2点を通る直線を考える．この直線の傾きがとり得る範囲を求めなさい．ただし，2点が一致するときは，その点における接線を考えるものとする．
\end{enumerate}

\begin{enumerate}
  \item $a,b$ を異なる実数とし，関数 $f(x)$ が $a,b$ を含む区間で第2次導関数 $f''(x)$ を持ち $f''(x)>0$ が成り立つものとする．このとき $0\leqq t\leqq1$ に対して，$tf(a)+(1-t)f(b)\geqq f(ta+(1-t)b)$ が成り立つことを示せ．
  \item (1) の条件の下で（3点を含む区間で），$\dfrac{f(a)+f(b)+f(c)}3\geqq f\left(\dfrac{a+b+c}3\right)$ を示せ．
  \item $f(x)=x\log x$ に (2) を適用することにより，正の数 $a,b,c$ に対して，$a^ab^bc^c\geqq\left(\dfrac{a+b+c}3\right)^{a+b+c}$ が成り立つことを示せ．
\end{enumerate}

\begin{enumerate}
  \item $p\geqq1$，$t>0$ に対して，不等式 $t^p\geqq1+p(t-1)$ が成り立つことを示せ．
  \item $x>0$，$y>0$ と $0<q<1$ に対して，不等式 $qx+(1-q)y\geqq x^qy^{1-q}$ が成り立つことを示せ．
  \item $x>0$，$y>0$ に対して，不等式 $2x^3+y^3\geqq3x^2y$ が成り立つことを示せ．
\end{enumerate}

次の問いに答えよ．
\begin{enumerate}
  \item $a>0$，$a\neq1$ とする．このとき $x>0$ で定義された関数 $f(x)=(1+a^x)^{\frac1x}$ は減少関数であることを示せ．
  \item 次の4つの数の中から最小の数と最大の数を選べ．
  \[
  (3^{10}+4^{10})^{\frac1{10}},\quad(3^{11}+4^{11})^{\frac1{11}},\quad\left(3^{\frac1{10}}+4^{\frac1{10}}\right)^{10},\quad\left(3^{\frac1{11}}+4^{\frac1{11}}\right)^{11}
  \]
  \item $p_1,\dots,p_n$ を正の数とするとき，$\displaystyle\lim_{x\to\infty}(p_1^x+\dots+p_n^x)^{\frac1x}$ を求めよ．
\end{enumerate}

次の問いに答えよ．
\begin{enumerate}
  \item 関数 $g(x)=\dfrac{x-\sin x}{x^3}$ について，次の問いに答えよ．\\
  (i) $\displaystyle\lim_{x\to0}g(x)$ を求めよ．ただし $\displaystyle\lim_{x\to0}\frac{1-\cos x}{x^2}=\frac12$ は用いてよい．\\
  (ii) 区間 $0<x<\pi$ で $g(x)$ は減少することを示せ．
  \item 三角形ABCにおいて，$\angle$A，$\angle$B の大きさをそれぞれ $\alpha,\beta$ とする．$0<\alpha<\beta<\pi$ のとき，次の不等式が成り立つことを証明せよ．
  \[
  1<\frac{\beta-\sin\beta}{\alpha-\sin\alpha}<\frac{\beta^3}{\alpha^3}
  \]
\end{enumerate}

曲線 $y=\log x$ 上を動く点Pの時刻 $t$ における座標を $(x(t),y(t))$ と表し，Pの速度ベクトルと加速度ベクトルをそれぞれ $\vec v=\left(\dfrac{dx}{dt},\dfrac{dy}{dt}\right)$ と $\vec\alpha=\left(\dfrac{d^2x}{dt^2},\dfrac{d^2y}{dt^2}\right)$ とする．すべての時刻 $t$ で $|\vec v|=1$ かつ $\dfrac{dx}{dt}>0$ であるとして，次の問いに答えよ．
\begin{enumerate}
  \item Pが点 $(s,\log s)$ を通過する時刻における速度ベクトル $\vec v$ を $s$ を用いて表せ．
  \item Pが点 $(s,\log s)$ を通過する時刻における加速度ベクトル $\vec\alpha$ を $s$ を用いて表せ．
  \item Pが曲線全体を動くとき，$|\vec\alpha|$ の最大値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item すべての実数で微分可能な関数 $f(x)$ がつねに $f'(x)=0$ をみたすとする．このとき $f(x)$ は定数であることを示せ．
  \item 実数全体で定義された関数 $g(x)$ が次の条件 $(*)$ をみたすならば，$g(x)=x+(\text{定数})$ であることを示せ．\\
  $(*)$ 正の定数 $C$ が存在して，すべての実数 $x,y$ に対して $|g(x)-g(y)-(x-y)|\leqq C|x-y|^2$ が成り立つ．
\end{enumerate}

曲線 $C:y=x^3-x$ 上の点 $\mathrm P(a,a^3-a)$（$a>0$）における接線を $l$ とし，$l$ が再び $C$ と交わる点をQとする．Qにおける $C$ の接線を $m$ とし，$l$ と $m$ のなす角を $\theta$（$0<\theta<\frac\pi2$）とする．
\begin{enumerate}
  \item Qの $x$ 座標を求め，$\tan\theta$ を $a$ で表せ．
  \item $\theta$ を最大にする $a^2$ の値と，そのときの $\tan\theta$ を求めよ．
\end{enumerate}

$g_n(x)=1+x+\dfrac{x^2}{2!}+\dots+\dfrac{x^n}{n!}$（$n=1,2,\dots$）とする．
\begin{enumerate}
  \item $n$ が偶数のとき $g_n(x)>0$（すべての $x$），$n$ が奇数のとき $g_n(x)=0$ はただ1つの実数解をもつことを，同時に帰納法で示せ．
  \item $n=3$ の実数解 $x_3$ は $-2<x_3<-1$ にあることを示せ．
  \item $n=5$ の実数解 $x_5$ について $x_5<x_3$ を示せ．
\end{enumerate}

曲線 $y=\dfrac2x$（$x>0$）上の点P$\left(p,\dfrac2p\right)$ における接線 $l$ と $x$ 軸，$y$ 軸の交点をA，Bとし，原点Oから $l$ に下ろした垂線の足をQとする．次を示せ．
\begin{enumerate}
  \item PはABの中点であり，三角形OABの面積は一定である．
  \item 2直線OP，OQは直線 $y=x$ に関して対称である．
  \item 積 OP$\cdot$OQ は一定である．その値を求めよ．
\end{enumerate}

楕円 $\dfrac{x^2}9+\dfrac{y^2}4=1$ の第1象限の点における接線が，$x$ 軸，$y$ 軸の正の部分と交わる点をA，Bとする．
\begin{enumerate}
  \item 線分ABの長さの最小値を求めよ．
  \item OA$+$OB の最小値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 曲線 $y=\dfrac x{x^2+4x+3}$ の漸近線，極値を求め，概形を描け．
  \item 曲線 $x=\dfrac{1+t^2}{1-t^2}$，$y=\dfrac{2t}{1-t^2}$（$t\neq\pm1$）の $x,y$ の関係式を求め，曲線上にない点を答えよ．
\end{enumerate}

$f(x)=\dfrac{x-\sin x}{x^2}$（$x\neq0$），$f(0)=a$ とする．
\begin{enumerate}
  \item $f$ が連続となる $a$ を求めよ．
  \item (1) のとき $f'(0)$ を定義にしたがって求めよ．
  \item $f$ は $-\pi\leqq x\leqq\pi$ で増加関数であることを示せ．
\end{enumerate}

$f(x)=1+\dfrac13\sin x$ とする．
\begin{enumerate}
  \item 方程式 $f(x)=x$ はただ1つの実数解 $\alpha$ をもち，$1<\alpha<\frac43$ であることを示せ．
  \item 任意の実数 $x,y$ に対して $|f(x)-f(y)|\leqq\frac13|x-y|$ を示せ．
  \item $a_0=0$，$a_n=f(a_{n-1})$ で定めた数列は $\alpha$ に収束することを示し，$|a_n-\alpha|<10^{-3}$ となる $n$ を1つ求めよ．
\end{enumerate}

2曲線 $C_1:y=\sin x$，$C_2:y=\dfrac1{\tan x}$（$0<x<\frac\pi2$）がある．
\begin{enumerate}
  \item 交点Pの $x$ 座標を $x_0$ とするとき，$\cos x_0$ の値を求めよ．
  \item Pにおける $C_1$ の接線と $C_2$ の接線は直交することを示せ．
  \item Pにおける2本の接線と $x$ 軸で囲まれる三角形の面積を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $f''(x)$ が存在するとき，$f(b)=f(a)+f'(a)(b-a)+\frac12f''(c)(b-a)^2$ となる $c$（$a$ と $b$ の間）が存在することを示せ．
  \item $f''(x)>0$ の区間内の $x_1,\dots,x_n$ に対して $\frac1n\sum f(x_i)\geqq f\left(\frac1n\sum x_i\right)$ を示せ（等号は全部等しいとき）．
  \item 正の数 $x_1,\dots,x_n$ について $(x_1+\dots+x_n)\left(\dfrac1{x_1}+\dots+\dfrac1{x_n}\right)\geqq n^2$ を (2) から導け．
\end{enumerate}

曲線 $C_1:y=e^x$ 上の点Pと曲線 $C_2:y=\log x$ 上の点Qは，P，Qにおける接線が平行であるように動く．
\begin{enumerate}
  \item P$(p,e^p)$ のとき，Qの座標を $p$ で表せ．
  \item PQ が最小となるとき，直線PQはPにおける $C_1$ の接線と直交することを示し，PQの最小値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x>0$ と自然数 $n$ に対し，$g_n(x)=\displaystyle\sum_{k=0}^n\frac{(-x)^k}{k!}$ とおく．$\left|e^{-x}-g_n(x)\right|<\dfrac{x^{n+1}}{(n+1)!}$ を示せ．
  \item $\frac1e$ が有理数 $\frac mn$（$m,n$ は自然数）であると仮定して，$n!\left(e^{-1}-g_n(1)\right)$ を考えることで矛盾を導け．
\end{enumerate}

関数 $f(x)$ は微分可能で，(i) $f(x)\geqq1+2x$，(ii) すべての実数 $x,h$ に対して $f(x+h)\geqq f(x)f(h)$ をみたしている．
\begin{enumerate}
  \item $f(0)$ と $f'(0)$ を求めよ．
  \item $f(x)>0$ を示し，$f'(x)=2f(x)$ を示して $f(x)$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 関数 $f(x)=x^{-4}4^x$（$x\neq0$）について，$f'(x)>0$ となる $x$ の範囲を求めよ．
  \item 方程式 $4^x=x^4$ は相異なる3個の実数解をもつことを示せ．
  \item 方程式 $4^x=x^4$ の解で有理数であるものをすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item すべての $t>0$ に対して $e^{\frac t2}-e^{-\frac t2}\geqq t$ を示せ．
  \item $a>0$ とする．すべての $t>0$ に対して $\dfrac{1-e^{-t}}t\geqq e^{-\frac ta}$ が成り立つような $a$ の範囲を求めよ．
\end{enumerate}

実数 $a$ に対して，曲線 $y=\sqrt x$ と直線 $y=a(x+1)+1$ を考える．
\begin{enumerate}
  \item 曲線と直線が共有点をもつような $a$ の範囲を求めよ．
  \item $0<a\leqq2$ とし，$u$ の2次方程式 $au^2-u+a+1=0$ の複素数の範囲での2解を $\alpha,\beta$（$|\alpha|\leqq|\beta|$）とする．$|\beta|$ の最小値を求めよ．
\end{enumerate}

関数 $f(x)=\dfrac{ax+b}{x+c}$ が次の条件 (A)，(B) をみたすとき，$a,b,c$ を求めよ．
\begin{itemize}
  \item[(A)] 曲線 $y=f(x)$ は直線 $y=x-1$ と2点で交わり，2交点の $x$ 座標は絶対値が等しく符号が異なる．
  \item[(B)] 曲線 $y=f(x)$ と $x$ 軸，$y$ 軸の交点はともに直線 $y=-2x+4$ 上にある．
\end{itemize}

\begin{enumerate}
  \item 方程式 $x+1=\sqrt{2x^2+4x+a}$ が実数解をもつための $a$ の条件と，そのときの解を求めよ．
  \item 不等式 $\sqrt{x+1}>ax+b$ の解が $-1\leqq x<3$ となるような正の数 $a,b$ について，$a+b$ のとり得る値の範囲を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 関数 $y=\dfrac{2^x-2^{-x}}2$（$x$ は実数全体）の逆関数を求めよ．
  \item (1) の逆関数を $g(x)$ とするとき，$g(x)=1$ となる $x$ と，$g\left(\frac{15}8\right)$ を求めよ．
\end{enumerate}

$f(x)=x^4+ax^3+bx^2+cx+d$ のグラフが $y$ 軸に平行な直線に関して対称であるとする．
\begin{enumerate}
  \item $a,b,c$ のみたす関係式を求めよ．
  \item $a=-8$，$b=18$ のとき $c$ を求め，$f(x)=g(h(x))$ となる2次関数 $g$，$h$ を1組求めよ．
  \item (2) で $d=0$ のとき，$f(x)$ の最小値を求めよ．
\end{enumerate}

$-1<x<1$ で定義された $f_p(x)=\dfrac{x-p}{1-px}$（$-1<p<1$）を考える．
\begin{enumerate}
  \item $-1<x<1$ ならば $-1<f_q(x)<1$ を示せ．
  \item $f_p(f_q(x))=f_r(x)$ となる $r$ を $p,q$ で表し，$-1<r<1$ を示せ．
  \item すべての $x$ で $f_p(f_p(x))=f_{\frac12}(x)$ となる $p$ を求めよ．
\end{enumerate}

$f_1(x)=x$，$f_2(x)=\dfrac1x$，$f_3(x)=1-x$，$f_4(x)=\dfrac1{1-x}$，$f_5(x)=\dfrac x{x-1}$，$f_6(x)=\dfrac{x-1}x$ とする（$x\neq0,1$）．以下 $a,b,k$ は $1,\dots,6$ のいずれか．
\begin{enumerate}
  \item $f_k(f_k(x))=f_1(x)$ となる $k$ をすべて求めよ．
  \item $f_3(f_a(x))=f_6(x)$ となる $a$，$f_b(f_4(x))=f_2(x)$ となる $b$ を求めよ．
  \item $f_4$ の逆関数は6つのうちのどれか．
\end{enumerate}

$f(x)=\sqrt x$（$x\geqq0$）の逆関数を $g(x)$ とする．$y\leqq f(x)$，$y\geqq g(x)$ を同時にみたす点 $(x,y)$ の集合を $M$ とし，$F(x,y)=ay+bx$ の $M$ 上の最小値を考える．
\begin{enumerate}
  \item $g(x)$ と $M$ を求めよ．
  \item $a=0$ のとき，$F$ の最小値を $b$ の符号で分けて求めよ．
  \item $a>0$ のとき，$F$ が $0<x<1$ の点で最小となるための $\frac ba$ の条件と，その最小値を求めよ．$a=4$，$b=-3$ のときの最小値を答えよ．
\end{enumerate}

$f(x)=\dfrac{2x}{1+x}$ とする．
\begin{enumerate}
  \item 実数 $t$ が $f(f(t))=f(t)$ をみたすとき，$f(t)=t$ も成り立つことを示し，そのような $t$ を求めよ．
  \item 不等式 $f(f(x))\geqq f(x)$ を解け．
\end{enumerate}

$n$ を2以上の自然数とする．
\begin{enumerate}
  \item 整式 $g(x)$ が $(x+1)^2$ で割り切れるための条件は $g(-1)=g'(-1)=0$ であることを示せ．
  \item $g(x)=ax^{n+1}+bx^n+1$ が $(x+1)^2$ で割り切れるとき，$a,b$ を $n$ で表せ．
\end{enumerate}

$f(x)$ はすべての実数で微分可能で，$f(2x)=(e^x+e^{-x})f(x)$ をみたす．$s(x)=\dfrac{e^x-e^{-x}}2$ とする．
\begin{enumerate}
  \item $f(0)=0$ を示せ．
  \item $x\neq0$ に対して $\dfrac{f(x)}{s(x)}=\dfrac{f(\frac x2)}{s(\frac x2)}$ を示せ．
  \item $f(x)=f'(0)s(x)$ を示せ．
\end{enumerate}

\begin{enumerate}
  \item $y=\tan x$（$-\frac\pi2<x<\frac\pi2$）の逆関数を $y=f(x)$ とするとき，$f'(x)$ を求めよ．
  \item $g(x)=\dfrac{e^x+e^{-x}}2$（$x\geqq0$）の逆関数を $h(x)$（$x\geqq1$）とする．$x>1$ で $h'(x)$ を求め，$(x^2-1)h'''(x)+3xh''(x)$ を $h'(x)$ で表せ．
\end{enumerate}

$x\geqq0$ で定義された $f(x)=xe^{x^2}$ の逆関数を $g(x)$ とする．
\begin{enumerate}
  \item $f'(1)$，$f''(1)$ を求めよ．
  \item $g'(e)$，$g''(e)$ を求めよ．
\end{enumerate}

$n$ 次の整式 $T_n(x)$ は $T_n(\cos\theta)=\cos n\theta$ をみたす（$n=1,2,\dots$）．
\begin{enumerate}
  \item $T_n'(\cos\theta)=\dfrac{n\sin n\theta}{\sin\theta}$（$\sin\theta\neq0$）を示し，$T_n'(1)$ を求めよ．
  \item $T_n''(\cos\theta)$ を $\theta$ で表し，$T_n''(1)=\dfrac{n^2(n^2-1)}3$ を示せ．
\end{enumerate}

微分可能な関数 $f(x)$ が任意の実数 $x,y$ で $f(x+y)=f(x)\sqrt{1+f(y)^2}+f(y)\sqrt{1+f(x)^2}$ をみたす．
\begin{enumerate}
  \item $f(0)$ を求め，$f(-x)=-f(x)$ を示せ．
  \item $f'(0)=2$ のとき，$f'(x)$ を $f(x)$ で表せ．
  \item (2) のとき $f(x)$ を求めよ．
\end{enumerate}

$c>1$ とし，$f(x)$ は微分可能ですべての $x$ で $f'(x)\geqq c$ をみたす．
\begin{enumerate}
  \item $x\geqq0$ で $f(x)-f(0)\geqq cx$，$x\leqq0$ で $f(x)-f(0)\leqq cx$ を示せ．
  \item 方程式 $f(x)=x$ はただ1つの実数解をもつことを示せ．
\end{enumerate}

$f(x)=\dfrac x2\left\{1+e^{-3(x-1)}\right\}$ とする．
\begin{enumerate}
  \item $x>\frac13$ ならば $|f'(x)|\leqq\dfrac{e-1}2$ であることを示せ．
  \item $x>\frac13$ ならば $f(x)>\frac13$ であることを示せ．
  \item $x_0>\frac13$，$x_{n+1}=f(x_n)$ のとき $\displaystyle\lim_{n\to\infty}x_n=1$ を示せ．
\end{enumerate}

$f(x)=\dfrac1{1+x^2}$ を $x>0$ で考える．点 $(a,f(a))$ における接線を $l_a$，その $y$ 切片を $Y(a)$ とする．
\begin{enumerate}
  \item $Y(a)$ のとり得る値の範囲を求めよ．
  \item $0<a<b$ で $l_a$ と $l_b$ が $x$ 軸上で交わるとき，$a$ の範囲を求め，$b$ を $a$ で表せ．
  \item (2) のとき $Z(a)=Y(a)-Y(b)$ とする．$\displaystyle\lim_{a\to+0}Z(a)$ と $\displaystyle\lim_{a\to+0}\frac{Z'(a)}a$ を求めよ．
\end{enumerate}

$n$ を正の整数とする．
\begin{enumerate}
  \item 正の整数 $k$ に対して $(1-x)^nx^k$ の $0\leqq x\leqq1$ での最大値 $a_n$ を求め，$\displaystyle\lim_{n\to\infty}n^ka_n$ を求めよ．
  \item $p\geqq0$，$q>0$ とし，$(1-x)^n(px^2+qx)$ の $0\leqq x\leqq1$ での最大値を $e_n$ とする．$\displaystyle\lim_{n\to\infty}ne_n$ を求めよ．
\end{enumerate}

平面上を半径1の3つの円板が，(a) 中心はいずれも定点Pを中心とする半径1の円周上にある，(b) 3つすべてが共有する点はPのみである，をみたしながら動く．Pから見た隣り合う中心の間の角を $\alpha_1,\alpha_2,\alpha_3$（和 $2\pi$）とする．
\begin{enumerate}
  \item 中心間の角が $\varphi$（$0\leqq\varphi\leqq\pi$）の2つの円板の共通部分の面積は $\pi-\varphi-\sin\varphi$ であることを示せ．
  \item (b) より $\alpha_i\leqq\pi$ であることを用いて，3つの円板の和集合の面積を $\alpha_i$ で表せ．
  \item $\alpha_1=\frac\pi2$ のとき，和集合の面積の最大値を求めよ．
\end{enumerate}

A$(-1,0)$，B$(1,0)$ からの距離の積が $\frac32$ である点の軌跡を $C$ とする．
\begin{enumerate}
  \item $C$ の方程式を求め，$x$ 軸，$y$ 軸に関して対称であることを示せ．
  \item $C$ と $x$ 軸，$y$ 軸の交点を求めよ．
  \item $C$ 上の点の $y$ 座標の最大値と，そのときの $x$ を求め，$C$ の概形の特徴を述べよ．
\end{enumerate}

\begin{enumerate}
  \item $t>0$ で定義された $f(t)=e^{-t}\cos t$ が極値をとる $t$ を小さい順に $t_1,t_2,\dots$ とする．$t_n$ と $f(t_n)$ を求めよ．
  \item 曲線 $C:x=e^t\cos t$，$y=e^t\sin t$（$t>0$）と点 P$(r,0)$（$r>0$）がある．$C$ の接線で P を通るものの本数を $N(r)$ とする．$N(r)=1$ となる $r$ の範囲，$N(r)=2$ となる $r$ の値，$N(r)=3$ となる $r$ の範囲を求めよ．
\end{enumerate}

$k$ を正の整数とし，$(2k-1)\pi\leqq x\leqq2k\pi$ で2曲線 $C_1:y=\cos x$，$C_2:y=\dfrac{x^2-1}{x^2+1}$ を考える．
\begin{enumerate}
  \item $C_1$ と $C_2$ は共有点をもち，その点における $C_1$ の接線は点 $(0,-1)$ を通ることを示せ．
  \item $C_1$ と $C_2$ の共有点はただ1つであることを示せ．
\end{enumerate}

曲線 $C:y=\dfrac{e^x+e^{-x}}2$ の上を，速さ1で $x$ 成分が正となるように点 P が動く．点 Q を P における $C$ の法線上にあり PQ$=1$ で，領域 $y<\dfrac{e^x+e^{-x}}2$ にある点とする．
\begin{enumerate}
  \item P$\left(u,\frac{e^u+e^{-u}}2\right)$ のとき，Q の座標を求めよ．
  \item Q の速さのとり得る値の範囲を求めよ．
\end{enumerate}

点 P$(0,1)$ を中心とする半径1の円を $C$ とする．$a>0$ とし，直線 $y=a(x+1)$ と $C$ の2つの交点を Q，R とする．
\begin{enumerate}
  \item $\triangle$OQR の面積 $S(a)$ を求めよ（O は原点）．
  \item $S(a)$ が最大となる $a$ と最大値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $t>0$ のとき $\dfrac{2t}{2+t}<\log(1+t)<t$ を示せ．
  \item $x>0$ のとき $\left(1+\dfrac1x\right)^x<e<\left(1+\dfrac1x\right)^{x+\frac12}$ を示せ．
  \item 「すべての $x>0$ に対して $\left(1+\dfrac1x\right)^{x+c}>e$」が成り立つような定数 $c$ の最小値を求めよ．
\end{enumerate}

$x>1$ で $f(x)=\dfrac{(x+1)\log x}{x-1}$ とする．
\begin{enumerate}
  \item $\displaystyle\lim_{x\to1+0}f(x)$ を求めよ．
  \item $f(x)$ は $x>1$ で単調に増加することを示せ．
  \item $x>1$ のとき $\log x>\dfrac{2(x-1)}{x+1}$ を示せ．
\end{enumerate}

$y=\log\dfrac{\sqrt{x+5}-\sqrt x}{\sqrt{x+5}+\sqrt x}$（$x>0$）とする．
\begin{enumerate}
  \item $\dfrac{dy}{dx}$ を求め，できるだけ簡単な形で表せ．
  \item 曲線の $x=4$ における接線の方程式を求めよ．
  \item $\displaystyle\int_4^{20}\frac{dx}{\sqrt{x(x+5)}}$ を求めよ．
\end{enumerate}

$f(x)=\dfrac x{x^2-2x+4}$，$g(x)=\dfrac{x^2}{x^2-2x+4}$ とする．
\begin{enumerate}
  \item $f(x)$ の最大値と最小値を求めよ．
  \item $g(x)$ の最大値と最小値を求めよ．
  \item $f(x)+g(x)=\dfrac{x^2+x}{x^2-2x+4}$ の最大値は，(1)(2) の最大値の和より小さいことを示し，実際の最大値を求めよ．
\end{enumerate}

$xy$ 平面上の曲線 $y=x^2$ を $y$ 軸のまわりに1回転してできる曲面を $S$ とする．
\begin{enumerate}
  \item 点 $\mathrm A\left(2\sqrt3,-\frac12,2\right)$ から $S$ にいたる最短距離と，最短距離を与える $S$ 上の点の座標を求めよ．
  \item $b>0$ とする．点 $(0,b,0)$ から $S$ にいたる最短距離を $b$ で表し，最短距離を与える $S$ 上の点全体がどのような図形になるかを答えよ．
\end{enumerate}

$n$ を自然数とし，$g(x)=\displaystyle\sum_{k=1}^n\frac{x^{k+2}}{k(k+1)(k+2)}$ とする．
\begin{enumerate}
  \item $-1\leqq x\leqq1$ で $g'''(x)\geqq0$ を示せ．
  \item $g(x)$ は $-1\leqq x\leqq1$ で増加することを示せ．
  \item $-1\leqq x\leqq1$ において $-\dfrac16\leqq g(x)<\dfrac14$ が成り立つことを示せ．
\end{enumerate}

\begin{enumerate}
  \item $a>0$ とする．曲線 $C_1:y^2=x(x-a)^2$ は $0\leqq x\leqq a$ の部分でループをつくる．ループ上で $|y|$ が最大となる点，点 $(a,0)$ における2本の接線の傾き，およびループで囲まれる部分の面積を求めよ．
  \item 曲線 $C_2:x=t+\dfrac1{t^2}$，$y=t^2+\dfrac2t$（$t>0$）について，接線が $y$ 軸に平行になる点と $x$ 軸に平行になる点を求めよ．また $\displaystyle\lim_{t\to+0}\frac{y^2}x$ と $\displaystyle\lim_{t\to\infty}\frac y{x^2}$ を求めよ．
  \item 極方程式 $r=1+2\cos\theta$（$0\leqq\theta<2\pi$）で表される曲線の内側のループで囲まれる部分の面積を求めよ．
\end{enumerate}

方程式 $x^3+x-1=0$ の実数解を $\alpha$ とする．正の定数 $\lambda$ に対して $g(x)=x-\lambda(x^3+x-1)$ とおき，$a_1\in[0,1]$，$a_{n+1}=g(a_n)$ で数列を定める．
\begin{enumerate}
  \item $0<\alpha<1$ であり，$\alpha$ がただ1つの実数解であることを示せ．
  \item $0\leqq x\leqq1$ における $|g'(x)|$ の最大値 $k(\lambda)$ を求め，$k(\lambda)$ を最小にする $\lambda$ とその最小値を求めよ．
  \item (2) の $\lambda$ に対して，$g$ は区間 $[0,1]$ をそれ自身に移すことを示し，$|a_n-\alpha|\leqq\left(\dfrac35\right)^{n-1}$ を示せ．
\end{enumerate}

$f(x)$ は微分可能で，つねに $f(x)>0$ かつ $f'(x)\leqq-\{f(x)\}^2$ をみたすとする．
\begin{enumerate}
  \item $f$ が $x>0$ で定義され $f(1)=1$ のとき，$x\geqq1$ で $f(x)\leqq\dfrac1x$ を示し，$\displaystyle\lim_{x\to\infty}f(x)$ を求めよ．また，$0<x<1$ で $f(x)\geqq\dfrac1x$ を示せ．
  \item このような $f$ で，実数全体で定義されたものは存在しないことを示せ．
\end{enumerate}

\begin{enumerate}
  \item 関数 $f(t)=\dfrac{\log t}t$（$t>0$）の増減と極限を調べ，グラフの概形を描け．
  \item 正の数 $x<y$ が $x^y=y^x$ をみたすとき，$x<e<y$，$xy>e^2$，$x+y>2e$ を示せ．
  \item $x\neq y$ である正の整数の組で $x^{2y}=y^x$ をみたすものをすべて求めよ．
\end{enumerate}

$0<a<\frac1e$ である $a$ に対して $xe^{-x}=a$ をみたす $x$ は2つある．小さい方を $u$，大きい方を $v$ とする．
\begin{enumerate}
  \item $\dfrac{du}{da}$，$\dfrac{dv}{da}$ を $u,v$ で表せ．
  \item $r=\dfrac vu$ とおくとき，$u,v$ を $r$ で表し，$u+v>2$ を示せ．
  \item $uv$ のとり得る値の範囲を求めよ．
\end{enumerate}

1辺の長さ2の正三角形ABCで，Aから辺BCに下ろした垂線をAHとする．線分AH上（両端を除く）に中心Oをもつ半径1の円 $C$ を考え，三角形の3つの辺（線分）がいずれも，辺の両端以外の異なる2点で $C$ の周と交わるとき $\mathrm{AO}=x$ とおく．三角形ABCと円 $C$ の内部の共通部分の面積を $S$ とし，$F(t)=2\displaystyle\int_t^1\sqrt{1-u^2}\,du$（$0\leqq t\leqq1$）とする．
\begin{enumerate}
  \item $x$ のとり得る値の範囲を求めよ．
  \item $S$ を $F$ を用いて表せ．
  \item $S$ を最大にする $x$ と，$S$ の最大値を求めよ．
\end{enumerate}

面積が1の正 $n$ 角形（$n\geqq3$）の周の長さを $L_n$ とする．
\begin{enumerate}
  \item $L_n$ を求めよ．
  \item $3\leqq n<m$ のとき $L_n>L_m$ を示せ．
  \item $\displaystyle\lim_{n\to\infty}L_n$ と $\displaystyle\lim_{n\to\infty}n^2(L_n-\lim_{m\to\infty}L_m)$ を求めよ．
\end{enumerate}

$f(x)=x^2\left(2+\sin\dfrac1x\right)$（$x\neq0$），$f(0)=0$ とする．
\begin{enumerate}
  \item $f$ は $x=0$ で微分可能であることを示し，$f'(0)$ を求めよ．
  \item $f$ は $x=0$ で最小値をとることを示せ．
  \item どんな $\delta>0$ に対しても，$f$ は区間 $(0,\delta)$ で単調増加ではないことを示せ．
\end{enumerate}

$a>0$ とし，曲線 $C_1:y=ax\sin x$，$C_2:y=\cos x$ を考える．
\begin{enumerate}
  \item $C_1$ と $C_2$ は無数に多くの交点をもつことを示せ．
  \item $C_1,C_2$ のすべての交点で2曲線の接線が直交するための $a$ の条件を求めよ．また，その条件をみたさない $a$ では，どの交点でも接線は直交しないことを示せ．
\end{enumerate}

放物線 $C:y=\dfrac{x^2}4$ の焦点を F$(0,1)$ とする．$C$ 上を動く点Pの時刻 $t$ における座標を $(x(t),y(t))$ とし，$x(0)=0$，$x(t)\geqq0$ とする．線分OF，FPと弧OPで囲まれた部分の面積 $S(t)$ がつねに $\dfrac{dS}{dt}=\dfrac12$ をみたすとき，
\begin{enumerate}
  \item $\dfrac{dx}{dt}$ を $x$ で表し，PF の長さを $x$ で表せ．
  \item 加速度ベクトル $\vec\alpha$ は $\overrightarrow{\mathrm{PF}}$ と同じ向きであることを示し，$|\vec\alpha|\cdot\mathrm{PF}^2$ の値を求めよ．
\end{enumerate}

$f(x)$ は2回微分可能とし，曲線 $C:y=f(x)$ 上の点 P$(p,f(p))$ における法線を $l_{\mathrm P}$，$C$ 上の P と異なる点 Q$(q,f(q))$ における法線を $l_{\mathrm Q}$ とする．$l_{\mathrm P}$ と $l_{\mathrm Q}$ の交点をRとし，Q が P に近づくときに R が近づく点を T とする（$f''(p)\neq0$）．
\begin{enumerate}
  \item T の座標と線分PTの長さを $p,f(p),f'(p),f''(p)$ で表せ．
  \item $f(x)=\dfrac1x$（$x>0$）とし，P が $C$ 上を動くとき，PT の最小値とそのときの T の座標を求めよ．
\end{enumerate}

$a$ を正の定数とする．第1象限にある曲線 $C:y=f(x)$ は2回微分可能で $f''(x)>0$ をみたし，$C$ 上の任意の点における接線は $x$ 軸，$y$ 軸の正の部分とそれぞれ P，Q で交わり，つねに $\mathrm{OP}+\mathrm{OQ}=a$ が成り立つ（O は原点）．
\begin{enumerate}
  \item $f(x)$ を求めよ（定義域も答えよ）．
  \item $x$ 切片 $p$，$y$ 切片 $a-p$（$0<p<a$）の線分全体が通過する範囲は，$x>0$，$y>0$，$\sqrt x+\sqrt y\leqq\sqrt a$ であることを示せ．
  \item (2) の範囲の面積を求めよ．
\end{enumerate}

$c>0$ とし，$x>0$ の範囲で方程式 $e^x=cx^2$ を考える．$\displaystyle\lim_{x\to\infty}\frac{e^x}{x^2}=\infty$ は証明なしに使ってよい．
\begin{enumerate}
  \item $x>0$ の範囲に異なる2つの解をもつような $c$ の範囲を求めよ．
  \item $c$ が (1) の範囲にあるとき，2つの解を $\alpha<\beta$ とする．$0<\alpha<2<\beta$ と $\alpha\beta<4$ を示せ．
  \item 同じく $\alpha+\beta>4$ を示せ．
\end{enumerate}

(I) $a$ を実数とし，$f(x)=|x|(e^{3x}+a)$ が $x=0$ で微分可能であるとする．
\begin{enumerate}
  \item $a$ および $f'(0)$ の値を求めよ．
  \item 導関数 $f'(x)$ は $x=0$ で連続であることを示せ．
  \item 右側極限 $\displaystyle\lim_{x\to+0}\frac{f'(x)}x$ と左側極限 $\displaystyle\lim_{x\to-0}\frac{f'(x)}x$ を求め，$f'(x)$ は $x=0$ で微分可能でないことを示せ．
\end{enumerate}
(II) $f(x)$ はすべての実数で微分可能で，$f(3x)=(e^{2x}+e^x+1)f(x)$ をみたす．
\begin{enumerate}
  \item $f(0)=0$ を示せ．
  \item $x\neq0$ に対して $\dfrac{f(x)}{e^x-1}=\dfrac{f(x/3)}{e^{x/3}-1}$ を示せ．
  \item $f(x)=(e^x-1)f'(0)$ を示せ．
\end{enumerate}

$x\geqq0$ で定義された関数 $f(x)=xe^{\frac x3}$ の逆関数を $g(x)$ とする．
\begin{enumerate}
  \item $f'(3)$，$f''(3)$ を求めよ．
  \item $g'(3e)$，$g''(3e)$ を求めよ．
  \item 曲線 $y=g(x)$ は $x>0$ で上に凸であることを示せ．
\end{enumerate}

$f(x)=\dfrac{x^3+x^2}{x^2-2}$ とする．
\begin{enumerate}
  \item $f(x)$ の増減を調べ，極値を求めよ．
  \item 曲線 $y=f(x)$ の漸近線を求めよ．
  \item 曲線 $y=f(x)$ の概形を描け．
\end{enumerate}

$f(x)=\dfrac{x+3}{\sqrt{x+1}}$（$x>-1$）とする．$y$ 軸上の点 $\mathrm A(0,b)$ から曲線 $y=f(x)$ に引ける接線の本数を考える．
\begin{enumerate}
  \item 接点の $x$ 座標を $t$ とするとき，$b=B(t)$ と表せ．
  \item 曲線 $y=f(x)$ のどの接線も，曲線と2点で接することはないことを示せ．
  \item 異なる接線がちょうど2本引けるような $b$ の値をすべて求めよ．また，ちょうど3本引ける $b$ の範囲を求めよ．
\end{enumerate}

$xy$ 平面上に曲線 $C:y=\dfrac{x^2}2$ がある．$C$ 上にない点 $\mathrm A(X,Y)$ と $C$ 上の点 P に対し，P における $C$ の接線と直線 AP が垂直であるとき，線分 AP を A から $C$ に下ろした垂線という．
\begin{enumerate}
  \item $C$ に異なる3本の垂線を下ろせる点 A の範囲を求め，図示せよ．
  \item A が (1) の範囲にあるとき，3本の垂線の足を頂点とする三角形の重心の座標を $X,Y$ で表せ．
  \item A が $y$ 軸上にあり，3本の垂線の足が正三角形の頂点となるとき，A の座標を求めよ．
\end{enumerate}

定数 $a$ に対して，$xy$ 平面の曲線 $C_a:y=(x-a)^2\{1-\log(x-a)\}$（$x>a$）を考える．
\begin{enumerate}
  \item $a=0$ のときの曲線 $C_0$ の概形を，増減・凹凸・極限を調べてかけ．ただし $\displaystyle\lim_{x\to+0}x^2\log x=0$ を用いてよい．
  \item $a$ を $a\geqq0$ の範囲で動かすとき，曲線 $C_a$ が通る部分を図示せよ．
\end{enumerate}

連立不等式 $x^2+(y-1)^2\leqq1$，$x\geqq\dfrac{\sqrt3}6$ で定まる領域を $D$ とする．原点を通り $x$ 軸と角 $\theta$（$0<\theta<\frac\pi2$）をなす直線 $l$ と $D$ の共通部分が線分となるとき，その長さを $L$ とする．
\begin{enumerate}
  \item 共通部分が線分となるための $\theta$ の条件を $\sin2\theta$ で表せ．
  \item $L$ の最大値と，そのときの $\cos\theta$ を求めよ．
\end{enumerate}

平面上の定点 P を中心とする半径1の円周上に中心をもつ，半径1の円板を考える．
\begin{enumerate}
  \item 中心 $\mathrm O_1$，$\mathrm O_2$ をもつ2枚の円板について，$\angle\mathrm O_1\mathrm P\mathrm O_2=\varphi$（$0<\varphi\leqq\pi$）のとき，共通部分の面積は $\pi-\varphi-\sin\varphi$ であることを示せ．
  \item 4枚の円板の中心が長方形の4頂点をなすとき，4枚すべてに共通な点は P のみであることを示せ．さらに，隣り合う中心が P から見て角 $\varphi$ をなすとして，和集合の面積 $S(\varphi)$ を求め，その最大値を求めよ．
  \item 3枚の円板の中心が P から見て順に $90^\circ$，$90^\circ$，$180^\circ$ の角をなすように並ぶとき，和集合の面積を求めよ．
\end{enumerate}

関数 $f(x)=x^x$（$x>0$）と正の実数 $a$ について答えよ．
\begin{enumerate}
  \item $\dfrac12\leqq x\leqq\dfrac32$ における $f(x)f(2-x)$ の最大値と最小値を求めよ．
  \item $\dfrac12\leqq x\leqq\dfrac32$ における $\dfrac{f(x)f(2-x)f(a)^2}{f(ax)f(a(2-x))}$ の最小値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $n\geqq2$，$p_1,\dots,p_n>0$，$0<\alpha<\beta$ のとき，$\left(\sum p_i^\alpha\right)^{\frac1\alpha}>\left(\sum p_i^\beta\right)^{\frac1\beta}$ を示せ．
  \item 次の4つの数のうち最大のものと最小のものを答えよ．
  \[(3^{10}+5^{10})^{\frac1{10}},\ (3^{11}+5^{11})^{\frac1{11}},\ (3^{\frac1{10}}+5^{\frac1{10}})^{10},\ (3^{\frac1{11}}+5^{\frac1{11}})^{11}\]
  \item $M_\alpha=\left(\frac1n\sum p_i^\alpha\right)^{\frac1\alpha}$ とおく．$0<\alpha<\beta$ のとき $M_\alpha\leqq M_\beta$ を示し，(1) と大小の向きが逆になる理由を説明せよ．
\end{enumerate}

$n$ を自然数とする．
\begin{enumerate}
  \item $x\geqq0$ のとき，$0\leqq e^{-x}-(1-x)\leqq\dfrac{x^2}2$ を示せ．
  \item $0\leqq x\leqq n$ のとき，$0\leqq e^{-x}-\left(1-\dfrac xn\right)^n\leqq\dfrac{x^2}{2n}$ を示せ．
  \item $\left|\left(1-\dfrac1n\right)^n-\dfrac1e\right|\leqq\dfrac1{2n}$ を示し，$\displaystyle\lim_{n\to\infty}\left(1-\frac1n\right)^n$ を求めよ．
\end{enumerate}

楕円 $\dfrac{x^2}4+y^2=1$ の $y>0$ の部分を，点 P$(x,y)$ が速さ一定 $C$ で，$x$ が増加する向きに動く．
\begin{enumerate}
  \item P の速度ベクトル $\vec v=\left(\dfrac{dx}{dt},\dfrac{dy}{dt}\right)$ を $x$ で表せ．
  \item P の加速度ベクトル $\vec\alpha$ を $x$ で表し，その大きさを求めよ．
  \item 半径 $r$ の円周上を速さ $C$ で動く点の加速度の大きさは $\frac{C^2}r$ である．P が点 $(0,1)$ にあるときの加速度の大きさがこれと等しくなる $r$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\dfrac\pi4\leqq a<\dfrac\pi2$，$\dfrac\pi4\leqq b<\dfrac\pi2$ のとき，次を示せ．
  \[\tan\frac{a+b}2\leqq\sqrt{\tan a\tan b}\leqq\frac{\tan a+\tan b}2\]
  \item (1) の左側の等号が成り立つための条件を求めよ．
  \item $0<a<\dfrac\pi4<b<\dfrac\pi2$，$a+b=\dfrac\pi2$ のとき，$\tan\dfrac{a+b}2$ と $\sqrt{\tan a\tan b}$ の大小を答えよ．
\end{enumerate}

$f(x)=\log\dfrac{x^2+3}{6}$ とし，曲線 $D:y=f(x)$ のすべての変曲点で $D$ に接する円を $C$ とする．
\begin{enumerate}
  \item $D$ の変曲点と $C$ の方程式を求めよ．
  \item $C$ と $D$ の共有点は $D$ の変曲点のみであることを証明せよ．
  \item $C$ と $D$ で囲まれた部分の面積を求めよ．
\end{enumerate}

$f(x)=-\dfrac{e^x+e^{-x}}2$ とし，曲線 $C:y=f(x)$ を考える．1辺の長さ $a$ の正方形 QRST（辺QRの対辺がST）は，最初，辺QRの中点Mが $C$ 上の点 $(0,f(0))$ に一致し，QRが $C$ に接し，正方形が $y>f(x)$ の側にあるようにおかれている．ついで，正方形が曲線 $C$ に接しながらすべることなく右に傾いてゆく．辺STの中点をNとする．
\begin{enumerate}
  \item 接点の $x$ 座標が $x$ のとき，Nの座標を $x$ と $a$ で表せ．
  \item 最初の状態から点Rが初めて $C$ 上にくるまでの間，Nの $y$ 座標が一定であるような $a$ を求めよ．
  \item (2) のとき，Rが $C$ 上にきた瞬間のNの座標を求めよ．
\end{enumerate}

$x\geqq0$ で定義された微分可能な関数 $f(x)$ は，$f(0)=0$，$x>0$ で $f'(x)>0$ をみたす．また，曲線 $C:y=f(x)$ 上で原点から点 $(x,f(x))$ までの長さは $\displaystyle\int_0^xf(u)\,du+x$ に等しい．
\begin{enumerate}
  \item $f(x)$ を求めよ．
  \item $C$ 上を動く点 $\mathrm P(x(t),y(t))$ の速度ベクトル $\vec v(t)$ は $x'(t)\geqq0$，$|\vec v(t)|=t$ をみたし，$(x(0),y(0))=(0,0)$ である．$t=\dfrac{\sqrt6}2$ における $\vec v$ を求めよ．
\end{enumerate}

$a\geqq b>0$，$n$ を自然数とする．
\begin{enumerate}
  \item $a^n-b^n\leqq\dfrac n2(a-b)(a^{n-1}+b^{n-1})$ を，$b$ を固定し $a$ を変数とみる方法で示せ．
  \item $a^n-b^n\geqq n(a-b)\left(\dfrac{a+b}2\right)^{n-1}$ を示せ．
  \item (1)，(2) の不等式がともに等号となるのは，どのようなときか．
\end{enumerate}

\begin{enumerate}
  \item $t>1$ のとき，$\dfrac{2(t-1)}{t+1}<\log t<\dfrac{t-1}{\sqrt t}$ を示せ．
  \item $a>1$ とし，曲線 $C:y=\log x$ 上の2点 $\mathrm P(a,\log a)$，$\mathrm Q\left(\frac1a,-\log a\right)$ における接線の交点を R とする．R の座標を求め，R は領域 $0<x<1$，$y>0$ にあることを示せ．
  \item R の座標を $(X,Y)$ とするとき，$\displaystyle\lim_{a\to1+0}\frac{1-X}{(a-1)^2}$ と $\displaystyle\lim_{a\to1+0}\frac Y{(a-1)^2}$ を求めよ．
\end{enumerate}

曲線 $y=\sin x$ の $x=t$（$\frac\pi2<t<\pi$）における接線と，$x$ 軸，$y$ 軸で囲まれる三角形の面積を $S(t)$ とする．
\begin{enumerate}
  \item $S(t)$ を $t$ の式で表せ．
  \item $S(t)$ はある1点 $t=t_0$ で最小値をとることを示せ．また，$\dfrac{7}{12}\pi<t_0<\dfrac23\pi$ を示せ．
  \item $S(t_0)=2t_0\sin t_0$ を示せ．また，$S(t_0)>\dfrac{7\sqrt3}{12}\pi$ を示せ．
\end{enumerate}

$x>0$ に対し $f(x)=\dfrac{\log x}{x^2}$ とする．
\begin{enumerate}
  \item $n=0,1,2,\dots$ に対し $f^{(n)}(x)=\dfrac{a_n+b_n\log x}{x^{n+2}}$（$a_n,b_n$ は定数）と表されることを示し，$a_n,b_n$ の漸化式を求めよ．ただし $f^{(0)}=f$ とする．
  \item $h_m=\displaystyle\sum_{k=1}^m\frac1k$ とおく．$a_n,b_n$ を $n$ と $h_{n+1}$ を用いて表せ．
  \item $n\geqq1$ のとき，$f^{(n)}(x)=0$ をみたす $x$ はただ1つであることを示し，それを $x_n$ とする．数列 $\{x_n\}$ は増加し，$\displaystyle\lim_{n\to\infty}x_n=\infty$ であることを示せ．
\end{enumerate}

$t$ を $0<t<1$ をみたす実数とする．$0$，$\dfrac1t$ 以外のすべての実数 $x$ で定義された関数
\[
f(x)=\frac{x^2+t}{x(1-tx)}
\]
を考える．
\begin{enumerate}
  \item $f(x)$ は極大値と極小値を1つずつもつことを示せ．
  \item $f(x)$ の極大値を与える $x$ の値を $\alpha$，極小値を与える $x$ の値を $\beta$ とし，座標平面上に2点 $\mathrm P(\alpha,f(\alpha))$，$\mathrm Q(\beta,f(\beta))$ をとる．$t$ が $0<t<1$ の範囲で変化するとき，線分 PQ の中点 M の軌跡を求めよ．
\end{enumerate}

$x>0$ に対し $f(x)=1000\log\left(1+\dfrac1x\right)$ とおく．ただし対数は自然対数とする．また，実数 $a$ に対し，$a$ を超えない最大の整数を $[a]$ で表す．
\begin{enumerate}
  \item $x>0$ のとき，次の不等式を証明せよ．
  \[
  \frac{1000}{(x+1)^2}<f(x)-f(x+1)<\frac{1000}{x(x+2)}
  \]
  \item $u>0$ のとき，$\log(1+u)<\dfrac{u(2+u)}{2(1+u)}$ を示せ．
  \item 1000個の整数 $[f(1)],\ [f(2)],\ \dots,\ [f(1000)]$ のうちで異なるものの個数を求めよ．
\end{enumerate}

空間に2定点 P，O を距離 $\mathrm{PO}=1$ となるようにとり，O を中心とする半径 $r\ (0<r<1)$ の球面 $S$ を考える．P から $S$ に引いた接線の接点全体は1つの円 $C$ をなす．P を頂点とし $C$ を底面の周とする直円錐から，球面 $S$ で囲まれた球体との共通部分を除いた立体を $K$ とする．
\begin{enumerate}
  \item $K$ の体積 $V(r)$ を $r$ で表し，$V(r)$ の最大値とそのときの $r$ の値を求めよ．
  \item $K$ の表面積 $T(r)$ を $r$ で表し，$T(r)$ の最大値とそのときの $r$ の値を求めよ．ただし，半径 $r$ の球面のうち1つの平面で切り取られた高さ $h$ の部分（球冠）の面積が $2\pi rh$ であることは用いてよい．
\end{enumerate}

\begin{enumerate}
  \item すべての正の実数 $x,y$ に対して
  \[
  \sqrt[3]x+\sqrt[3]y\leqq k\sqrt[3]{x+8y}
  \]
  が成り立つような実数 $k$ の最小値を求めよ．
  \item すべての正の実数 $x,y$ に対して
  \[
  \sqrt[3]x+\sqrt[3]y\geqq m\sqrt[3]{x+8y}
  \]
  が成り立つような実数 $m$ の最大値を求めよ．
\end{enumerate}

$e$ を自然対数の底とする．
\begin{enumerate}
  \item $x>0$ のとき，$\left(1+x+\dfrac{x^2}2+\dfrac{x^3}6\right)e^{-x}<1$ を示せ．
  \item $0<x<4$ のとき，次の不等式を示せ．
  \[
  1+x+\frac{x^2}2+\frac{x^3}6<e^x<\frac{24+18x+6x^2+x^3}{6(4-x)}
  \]
  \item (2) を用いて，$e$ の値を小数第2位まで求めよ（小数第3位以下は切り捨てる）．
\end{enumerate}

$\alpha,\beta,\gamma$ は $\alpha>0$，$\beta>0$，$\gamma>0$，$\alpha+\beta+\gamma=\pi$ をみたすものとする．
\begin{enumerate}
  \item $\sin^2\alpha\sin\beta\sin\gamma$ の最大値を求めよ．
  \item $\sin\alpha+\sin\beta\sin\gamma$ の最大値を求めよ．
\end{enumerate}

次の関数を微分せよ．\begin{enumerate}
  \item $y=(x^2+1)(2x-3)$
  \item $y=\dfrac{x}{x^2+1}$
\end{enumerate}

次の関数を微分せよ．\begin{enumerate}
  \item $y=(2x+1)^5$
  \item $y=\sqrt{x^2+3}$
\end{enumerate}

次の関数を微分せよ．\begin{enumerate}
  \item $y=\sin^2x$
  \item $y=\tan3x$
\end{enumerate}

次の関数を微分せよ．\begin{enumerate}
  \item $y=xe^{2x}$
  \item $y=\log(x^2+1)$
\end{enumerate}

関数 $f(x)=\dfrac{x^2+3}{x+1}$ について．\begin{enumerate}
  \item $f(x)$ の極値と，そのときの $x$ の値を求めよ．
  \item 曲線 $y=f(x)$ の漸近線のうち，$y$ 軸に平行でないものの方程式を求めよ．
\end{enumerate}

関数 $f(x)=\dfrac{\log x}{x}\ (x>0)$ について．\begin{enumerate}
  \item $f(x)$ の極大値を求めよ．
  \item 定数 $a>0$ について，方程式 $\log x=ax$ が異なる2つの正の実数解をもつような $a$ の値の範囲を求めよ．
\end{enumerate}

原点から曲線 $y=e^x$ に引いた接線について．\begin{enumerate}
  \item 接点の座標を求めよ．
  \item 接線の方程式を求めよ．
\end{enumerate}

座標平面上を動く点 P の時刻 $t$ における座標が $x=e^t\cos t,\ y=e^t\sin t$ で表されるとき．\begin{enumerate}
  \item 時刻 $t$ における P の速さを求めよ．
  \item 時刻 $t$ における P の加速度の大きさを求めよ．
\end{enumerate}

次の問いに答えよ．\begin{enumerate}
  \item $x$ が $0$ に近いとき，$\sqrt{1+x}$ の1次の近似式を求めよ．
  \item (1) を用いて $\sqrt{102}$ の近似値を求めよ．
\end{enumerate}

関数 $f(x)=x^3+x$ の逆関数を $g(x)$ とする．\begin{enumerate}
  \item $g(2)$ の値を求めよ．
  \item $g'(2)$ の値を求めよ．
\end{enumerate}

次の問いに答えよ．\begin{enumerate}
