  \item $x>0$ のとき，不等式 $x-\dfrac{x^2}{2}<\log(1+x)$ が成り立つことを証明せよ．
\end{enumerate}

曲線 $x^2+xy+y^2=3$ について．\begin{enumerate}
  \item $x+2y\neq0$ のとき，$\dfrac{dy}{dx}$ を $x,\ y$ の式で表せ．
  \item 曲線上の点 $(1,\ 1)$ における接線の方程式を求めよ．
\end{enumerate}

半径 $1$ の球に内接する直円柱について．\begin{enumerate}
  \item 円柱の体積が最大となるときの円柱の高さを求めよ．
  \item 円柱の体積の最大値を求めよ．
\end{enumerate}

関数 $f(x)=x^2e^{-x}$ について．\begin{enumerate}
  \item $f(x)$ の極大値と極小値を求めよ．
  \item 曲線 $y=f(x)$ の変曲点の $x$ 座標をすべて求めよ．
